 10	pub struct ListCommand;
 11	
 12	/// Serialize a slice of TimeEntry references as a JSON array,
 13	/// injecting a `"running"` boolean into each entry.
 14	fn time_entries_to_json(entries: &[&TimeEntry]) -> String {
 15	    let values: Vec<serde_json::Value> = entries
 16	        .iter()
 17	        .map(|entry| {
 18	            let mut value = serde_json::to_value(entry).expect("failed to serialize time entry");
 19	            if entry.is_running() {
 20	                if let Some(obj) = value.as_object_mut() {
 21	                    obj.insert("running".to_string(), serde_json::Value::Bool(true));
 22	                }
 23	            }
 24	            value
 25	        })
 26	        .collect();
 27	    serde_json::to_string(&values).expect("failed to serialize time entries to JSON")
 28	}
 29	
 30	fn write_entries_grouped_by_date(handle: &mut impl Write, entries: &[&TimeEntry]) {
 31	    let mut current_date: Option<chrono::NaiveDate> = None;
 32	    for entry in entries {
 33	        let local_start: DateTime<Local> = entry.start.with_timezone(&Local);
 34	        let date = local_start.date_naive();
 35	        if current_date != Some(date) {
 36	            if current_date.is_some() {
 37	                writeln!(handle).expect("failed to print");
 38	            }
 39	            writeln!(handle, "── {} ──", date.format("%Y-%m-%d %A")).expect("failed to print");
 40	            current_date = Some(date);
 41	        }
 42	        writeln!(handle, "{entry}").expect("failed to print");
 43	    }
 44	}
