 46	impl ListCommand {
 47	    pub async fn execute(
 48	        api_client: impl ApiClient,
 49	        count: Option<usize>,
 50	        json_flag: bool,
 51	        since: Option<String>,
 52	        until: Option<String>,
 53	        entity: Option<Entity>,
 54	    ) -> ResultWithDefaultError<()> {
 55	        let is_time_entry = matches!(entity, None | Some(Entity::TimeEntry { .. }));
 56	        let has_date_filter = since.is_some() || until.is_some();
 57	
 58	        if is_time_entry && has_date_filter {
 59	            let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
 60	            let stdout = io::stdout();
 61	            let mut handle = BufWriter::new(stdout);
 62	            let json = match &entity {
 63	                Some(Entity::TimeEntry { json }) => json_flag || *json,
 64	                _ => json_flag,
 65	            };
 66	            let entries = if json {
 67	                api_client
 68	                    .get_time_entries_filtered_minimal(since, until)
 69	                    .await
 70	            } else {
 71	                api_client.get_time_entries_filtered(since, until).await
 72	            };
 73	            match entries {
 74	                Err(error) => {
 75	                    return Err(error);
 76	                }
 77	                Ok(mut entries) => {
 78	                    entries.sort_by_key(|e| e.start);
 79	                    let entries = entries
 80	                        .iter()
 81	                        .take(count.unwrap_or(usize::MAX))
 82	                        .collect::<Vec<_>>();
 83	                    if json {
 84	                        let json_string = time_entries_to_json(&entries);
 85	                        writeln!(handle, "{json_string}").expect("failed to print");
 86	                    } else if entries.is_empty() {
 87	                        eprintln!("No entries found.");
 88	                    } else {
 89	                        write_entries_grouped_by_date(&mut handle, &entries);
 90	                    }
 91	                }
 92	            }
 93	            return Ok(());
 94	        }
 95	
 96	        if let Some(Entity::Tag { json: entity_json }) = entity {
 97	            let json = json_flag || entity_json;
 98	            let user = api_client.get_user().await?;
 99	            match api_client.get_tags(user.default_workspace_id).await {
100	                Err(error) => {
101	                    return Err(error);
102	                }
103	                Ok(tags) => {
104	                    let stdout = io::stdout();
105	                    let mut handle = BufWriter::new(stdout);
