139	impl Project {
140	    /// Gets the closest plain color to the TrueColor
141	    pub fn name_in_closest_terminal_color(&self, red: u8, green: u8, blue: u8) -> ColoredString {
142	        let colors = vec![
143	            (0, 0, 0),       //Black
144	            (205, 0, 0),     //Red
145	            (0, 205, 0),     //Green
146	            (205, 205, 0),   //Yellow
147	            (0, 0, 238),     //Blue
148	            (205, 0, 205),   //Magenta
149	            (0, 205, 205),   //Cyan
150	            (229, 229, 229), //White
151	            (127, 127, 127), //BrightBlack
152	            (255, 0, 0),     //BrightRed
153	            (0, 255, 0),     //BrightGreen
154	            (255, 255, 0),   //BrightYellow
155	            (92, 92, 255),   //BrightBlue
156	            (255, 0, 255),   //BrightMagenta
157	            (0, 255, 255),   //BrightCyan
158	            (255, 255, 255), //BrightWhite
159	        ]
160	        .into_iter()
161	        .enumerate();
162	
163	        let index = colors
164	            .map(|(index, (r, g, b))| {
165	                let rd = cmp::max(r, red) - cmp::min(r, red);
166	                let gd = cmp::max(g, green) - cmp::min(g, green);
167	                let bd = cmp::max(b, blue) - cmp::min(b, blue);
168	                let rd: u32 = rd.into();
169	                let gd: u32 = gd.into();
170	                let bd: u32 = bd.into();
171	                let distance: u32 = rd.pow(2) + gd.pow(2) + bd.pow(2);
172	                (distance, index)
173	            })
174	            .min_by(|(d1, _), (d2, _)| d1.cmp(d2))
175	            .unwrap()
176	            .1;
177	
178	        match index {
179	            0 => self.name.black(),
180	            1 => self.name.red(),
181	            2 => self.name.green(),
182	            3 => self.name.yellow(),
183	            4 => self.name.blue(),
184	            5 => self.name.magenta(),
185	            6 => self.name.cyan(),
186	            7 => self.name.white(),
187	            8 => self.name.bright_black(),
188	            9 => self.name.bright_red(),
189	            10 => self.name.bright_green(),
190	            11 => self.name.bright_yellow(),
191	            12 => self.name.bright_blue(),
192	            13 => self.name.bright_magenta(),
193	            14 => self.name.bright_cyan(),
194	            15 => self.name.bright_white(),
195	            _ => self.name.white().clear(),
196	        }
197	    }
198	}
