196	async fn execute_entry_command(
197	    action: EntryAction,
198	    proxy: Option<String>,
199	    picker: Box<dyn picker::ItemPicker>,
200	) -> ResultWithDefaultError<()> {
201	    // Validate required arguments BEFORE creating the API client to avoid
202	    // unnecessary keychain/storage access for validation failures.
203	    match &action {
204	        EntryAction::Show { id, current, .. } if id.is_none() && !current => {
205	            return Err(Box::new(error::ArgumentError::MissingArgument(
206	                "'show' requires an entry ID or --current flag. Run `toggl entry list` or `toggl entry running` to find one.".to_string(),
207	            )));
208	        }
209	        EntryAction::Update { id, current, .. } if id.is_none() && !current => {
210	            return Err(Box::new(error::ArgumentError::MissingArgument(
211	                "'edit' requires an entry ID or --current flag. Example: toggl entry edit --current -d \"New description\"".to_string(),
212	            )));
213	        }
214	        EntryAction::Update {
215	            description,
216	            billable,
217	            project,
218	            task,
219	            tags,
220	            start,
221	            end,
222	            ..
223	        } if description.is_none()
224	            && billable.is_none()
225	            && project.is_none()
226	            && task.is_none()
227	            && tags.is_none()
228	            && start.is_none()
229	            && end.is_none() =>
230	        {
231	            return Err(Box::new(error::ArgumentError::MissingUpdateFields(
232	                "No fields specified to update. Use -d, -p, -t, --billable, --tags, --start, or --end to specify what to change.".to_string(),
233	            )));
234	        }
235	        EntryAction::Delete { id, current, .. } if id.is_none() && !current => {
236	            return Err(Box::new(error::ArgumentError::MissingArgument(
237	                "'delete' requires an entry ID or --current flag. Run `toggl entry list` to find entry IDs.".to_string(),
238	            )));
239	        }
240	        EntryAction::BulkEdit { json: None, .. } => {
241	            return Err(Box::new(error::ArgumentError::MissingArgument(
242	                "'bulk-edit' requires --json flag with JSON payload".to_string(),
243	            )));
244	        }
245	        _ => {}
246	    }
247	
248	    let api_client = get_api_client(proxy.clone())?;
249	
250	    match action {
251	        EntryAction::Current { json } => RunningTimeEntryCommand::execute(api_client, json).await,
252	        EntryAction::List {
253	            number,
254	            json,
255	            since,
256	            until,
257	        } => ListCommand::execute(api_client, number, json, since, until, None).await,
258	        EntryAction::Stop { json } => {
259	            StopCommand::execute(&api_client, StopCommandOrigin::CommandLine, json).await?;
260	            Ok(())
261	        }
262	        EntryAction::Start {
263	            billable,
264	            description,
265	            project,
266	            task,
267	            tags,
268	            start,
269	            end,
270	            json,
271	        } => {
272	            StartCommand::execute(
273	                api_client,
274	                picker,
275	                description,
276	                project,
277	                task,
278	                tags,
279	                billable,
280	                false,
281	                start,
282	                end,
283	                json,
284	            )
285	            .await
286	        }
287	        EntryAction::Resume { id, json } => {
288	            ContinueCommand::execute(api_client, None, id, json).await
289	        }
290	        EntryAction::Show { id, current, json } => {
291	            if current {
292	                // Get the current running entry and show it
293	                match api_client.get_current_time_entry_minimal().await? {
294	                    Some(entry) => ShowCommand::execute(api_client, entry.id, json).await,
295	                    None => Err(Box::new(error::ArgumentError::ResourceNotFound(
296	                        "no time entry is currently running".to_string(),
297	                    ))),
298	                }
299	            } else {
300	                // id is guaranteed Some due to validation above
301	                ShowCommand::execute(api_client, id.unwrap(), json).await
302	            }
303	        }
304	        EntryAction::Update {
305	            id,
306	            current,
307	            description,
308	            billable,
309	            project,
310	            task,
311	            tags,
312	            start,
313	            end,
314	            json,
315	        } => {
316	            if current {
317	                // Check if there's a running entry before attempting edit
318	                match api_client.get_current_time_entry_minimal().await? {
319	                    Some(_) => {
320	                        // There's a running entry, let EditCommand handle it with id=None
321	                        EditCommand::execute(
