323	                            None,
324	                            description,
325	                            billable,
326	                            project,
327	                            task,
328	                            tags,
329	                            start,
330	                            end,
331	                            json,
332	                        )
333	                        .await
334	                    }
335	                    None => Err(Box::new(error::ArgumentError::ResourceNotFound(
336	                        "no time entry is currently running".to_string(),
337	                    ))),
338	                }
339	            } else {
340	                EditCommand::execute(
341	                    api_client,
342	                    id,
343	                    description,
344	                    billable,
345	                    project,
346	                    task,
347	                    tags,
348	                    start,
349	                    end,
350	                    json,
351	                )
352	                .await
353	            }
354	        }
355	        EntryAction::Delete { id, current, json } => {
356	            if current {
357	                // Get the current running entry and delete it
358	                match api_client.get_current_time_entry_minimal().await? {
359	                    Some(entry) => DeleteCommand::execute(api_client, entry.id, json).await,
360	                    None => Err(Box::new(error::ArgumentError::ResourceNotFound(
361	                        "no time entry is currently running".to_string(),
362	                    ))),
363	                }
364	            } else {
365	                // id is guaranteed Some due to validation above
366	                DeleteCommand::execute(api_client, id.unwrap(), json).await
367	            }
368	        }
369	        EntryAction::Search {
370	            query,
371	            project,
372	            no_project,
373	            tags,
374	            no_tag,
375	            since,
376	            until,
377	            number,
378	            order_by,
379	            order_dir,
380	            json,
381	        } => {
382	            commands::search::execute(
383	                api_client, query, project, no_project, tags, no_tag, since, until, number,
384	                order_by, order_dir, json,
385	            )
386	            .await
387	        }
388	        EntryAction::BulkEdit { ids, json } => {
389	            // json is guaranteed Some due to validation above
390	            BulkEditTimeEntriesCommand::execute(api_client, ids.clone(), json.clone().unwrap())
391	                .await
392	        }
393	    }
