 83	pub fn parse_datetime_input(input: &str) -> ResultWithDefaultError<DateTime<Utc>> {
 84	    let value = input.trim();
 85	    if value.is_empty() {
 86	        return Err(Box::new(ArgumentError::InvalidDateTime(input.to_string())));
 87	    }
 88	
 89	    // Natural language date/time keywords
 90	    match value.to_lowercase().as_str() {
 91	        "now" => return Ok(Utc::now()),
 92	        "today" => {
 93	            let today = Local::now().date_naive();
 94	            let naive = today.and_hms_opt(0, 0, 0).unwrap();
 95	            return match Local.from_local_datetime(&naive) {
 96	                LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
 97	                _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
 98	            };
 99	        }
100	        "yesterday" => {
101	            let yesterday = Local::now().date_naive().pred_opt().unwrap();
102	            let naive = yesterday.and_hms_opt(0, 0, 0).unwrap();
103	            return match Local.from_local_datetime(&naive) {
104	                LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
105	                _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
106	            };
107	        }
108	        "this_week" => {
109	            let today = Local::now().date_naive();
110	            let days_since_monday = today.weekday().num_days_from_monday();
111	            let monday = today - chrono::Duration::days(days_since_monday as i64);
112	            let naive = monday.and_hms_opt(0, 0, 0).unwrap();
113	            return match Local.from_local_datetime(&naive) {
114	                LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
115	                _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
116	            };
117	        }
118	        "last_week" => {
119	            let today = Local::now().date_naive();
120	            let days_since_monday = today.weekday().num_days_from_monday();
121	            let last_monday = today - chrono::Duration::days((days_since_monday + 7) as i64);
122	            let naive = last_monday.and_hms_opt(0, 0, 0).unwrap();
123	            return match Local.from_local_datetime(&naive) {
124	                LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
125	                _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
126	            };
127	        }
128	        _ => {}
129	    }
130	
131	    if let Ok(parsed) = DateTime::parse_from_rfc3339(value) {
132	        return Ok(parsed.with_timezone(&Utc));
133	    }
134	
135	    let local_formats = [
136	        "%Y-%m-%d %H:%M:%S",
137	        "%Y-%m-%d %H:%M",
138	        "%Y-%m-%dT%H:%M:%S",
139	        "%Y-%m-%dT%H:%M",
140	    ];
141	
142	    for format in local_formats {
143	        if let Ok(naive) = NaiveDateTime::parse_from_str(value, format) {
144	            return match Local.from_local_datetime(&naive) {
145	                LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
146	                _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
147	            };
148	        }
149	    }
150	
151	    if let Ok(date) = NaiveDate::parse_from_str(value, "%Y-%m-%d") {
152	        let naive = match date.and_hms_opt(0, 0, 0) {
153	            Some(naive) => naive,
154	            None => return Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
155	        };
156	        return match Local.from_local_datetime(&naive) {
157	            LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
158	            _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
159	        };
160	    }
161	
162	    // Time-only formats: HH:MM or HH:MM:SS (interpreted as today in local time)
163	    let time_formats = ["%H:%M:%S", "%H:%M"];
164	    for format in time_formats {
165	        if let Ok(time) = NaiveTime::parse_from_str(value, format) {
166	            let today = Local::now().date_naive();
167	            let naive = NaiveDateTime::new(today, time);
168	            return match Local.from_local_datetime(&naive) {
169	                LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
170	                _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
171	            };
172	        }
173	    }
174	
175	    Err(Box::new(ArgumentError::InvalidDateTime(input.to_string())))
176	}
177	
178	/// Like `parse_datetime_input`, but time-only values (HH:MM, HH:MM:SS) are
179	/// interpreted relative to `reference_date` instead of today.
180	pub fn parse_datetime_input_with_reference(
181	    input: &str,
182	    reference_date: NaiveDate,
183	) -> ResultWithDefaultError<DateTime<Utc>> {
184	    let value = input.trim();
185	
186	    // Time-only formats: use reference_date instead of today
187	    let time_formats = ["%H:%M:%S", "%H:%M"];
188	    for format in time_formats {
189	        if let Ok(time) = NaiveTime::parse_from_str(value, format) {
190	            let naive = NaiveDateTime::new(reference_date, time);
191	            return match Local.from_local_datetime(&naive) {
192	                LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
193	                _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
194	            };
195	        }
196	    }
197	
198	    // Fall back to the standard parser for all other formats
199	    parse_datetime_input(input)
200	}
