202	pub fn normalize_time_entry_list_filters(
203	    since: Option<String>,
204	    until: Option<String>,
205	) -> ResultWithDefaultError<(Option<String>, Option<String>)> {
206	    let since = since
207	        .as_deref()
208	        .map(|value| normalize_time_entry_list_filter(value, false))
209	        .transpose()?;
210	    let until = until
211	        .as_deref()
212	        .map(|value| normalize_time_entry_list_filter(value, true))
213	        .transpose()?;
214	
215	    // Official Toggl API requires both start_date and end_date.
216	    // Auto-fill missing --until to now, or missing --since to epoch.
217	    let since = since.or_else(|| {
218	        if until.is_some() {
219	            Some("1970-01-01T00:00:00Z".to_string())
220	        } else {
221	            None
222	        }
223	    });
224	    let until = until.or_else(|| {
225	        if since.is_some() {
226	            Some(Utc::now().format("%Y-%m-%dT%H:%M:%SZ").to_string())
227	        } else {
228	            None
229	        }
230	    });
231	
232	    // Validate that --since is not after --until
233	    if let (Some(since_val), Some(until_val)) = (&since, &until) {
234	        if since_val > until_val {
235	            return Err(Box::new(ArgumentError::InvalidTimeRange(
236	                "the --since date/time must not be after the --until date/time. \
237	                 Got reversed range: --since was later than --until. \
238	                 Hint: swap the values or use a valid date range."
239	                    .to_string(),
240	            )));
241	        }
242	    }
243	
244	    Ok((since, until))
245	}
246	
247	fn normalize_time_entry_list_filter(input: &str, is_until: bool) -> ResultWithDefaultError<String> {
248	    let value = input.trim();
249	    if let Ok(date) = NaiveDate::parse_from_str(value, "%Y-%m-%d") {
250	        let boundary_date = if is_until {
251	            match date.succ_opt() {
252	                Some(next_date) => next_date,
253	                None => return Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
254	            }
255	        } else {
256	            date
257	        };
258	        let naive = match boundary_date.and_hms_opt(0, 0, 0) {
259	            Some(naive) => naive,
260	            None => return Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
261	        };
262	        // Convert local time to UTC for API, ensuring proper RFC3339 format
263	        return match Local.from_local_datetime(&naive) {
264	            LocalResult::Single(local_dt) => {
265	                let utc_dt = local_dt.with_timezone(&Utc);
266	                Ok(utc_dt.format("%Y-%m-%dT%H:%M:%SZ").to_string())
267	            }
268	            LocalResult::None => {
269	                // Handle DST gaps by using UTC directly
270	                let utc_dt = Utc.from_utc_datetime(&naive);
271	                Ok(utc_dt.format("%Y-%m-%dT%H:%M:%SZ").to_string())
272	            }
273	            LocalResult::Ambiguous(dt1, _dt2) => {
274	                // Handle DST overlaps by using the first option
275	                let utc_dt = dt1.with_timezone(&Utc);
276	                Ok(utc_dt.format("%Y-%m-%dT%H:%M:%SZ").to_string())
277	            }
278	        };
279	    }
