      "wing": null,
      "room": null,
      "confidence": 0.0,
      "reason": "global search: no taxonomy keyword match"
    },
    "memory_kind": "evidence",
    "domain": "project",
    "field": "general",
    "anchor_kind": "repo",
    "anchor_id": "repo://legacy"
  }
]
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
        json_output: bool,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let totals = project_totals(&entries);
        let total_seconds: i64 = totals.iter().map(|(_, seconds)| seconds).sum();

        if json_output {
            let groups: Vec<_> = totals
                .iter()
                .map(|(project, seconds)| {
                    json!({
                        "project": project,
                        "seconds": seconds,
                    })
                })
                .collect();
            println!(
                "{}",
                json!({
                    "groups": groups,
                    "total_seconds": total_seconds,
                })
            );
        } else {
            for (project_name, seconds) in totals {
                println!(
                    "{}  {}",
                    utilities::format_duration_compact(seconds),
                    project_name
                );
            }
            println!(
                "{}  Total",
                utilities::format_duration_compact(total_seconds)
            );
        }

        Ok(())
    }
}

